<?php

declare(strict_types=1);
require dirname(__DIR__,2).'/vendor/autoload.php';
use App\Bootstrap\App; use App\Database\Database; use App\Support\PlatformAuth; use App\Support\Csrf; use App\Support\Session; use App\Modules\Subscriptions\SubscriptionPlanRepository; use function App\Support\e; use function App\Support\slugify;
new App(); $db=Database::connection(); PlatformAuth::requireAdmin($db); $repo=new SubscriptionPlanRepository($db);
if($_SERVER['REQUEST_METHOD']==='POST'){
 if(!Csrf::verify($_POST['_csrf']??null)){Session::flash('error','Your form session expired.');}
 else{
  $action=$_POST['action']??'';
  try{
   if($action==='create'){
    $name=trim((string)($_POST['name']??'')); $slug=slugify((string)($_POST['slug']??$name)); if($name===''||$slug==='')throw new RuntimeException('Plan name is required.');
    $id=$repo->create(['name'=>$name,'slug'=>$slug,'description'=>$_POST['description']??'','monthly_price'=>$_POST['monthly_price']??0,'annual_price'=>$_POST['annual_price']??0,'currency'=>$_POST['currency']??'KES','trial_days'=>$_POST['trial_days']??0,'is_active'=>isset($_POST['is_active']),'is_public'=>isset($_POST['is_public']),'is_featured'=>isset($_POST['is_featured']),'sort_order'=>$_POST['sort_order']??0]);
    Session::flash('success','Plan created.'); header('Location: ' . PlatformAuth::basePath() . '/plans?edit=' . $id); exit;
   }
   if($action==='update'){
    $id=(int)$_POST['id']; $name=trim((string)($_POST['name']??'')); $slug=slugify((string)($_POST['slug']??$name)); if($id<1||$name===''||$slug==='')throw new RuntimeException('Plan details are required.');
    $repo->update($id,['name'=>$name,'slug'=>$slug,'description'=>$_POST['description']??'','monthly_price'=>$_POST['monthly_price']??0,'annual_price'=>$_POST['annual_price']??0,'currency'=>$_POST['currency']??'KES','trial_days'=>$_POST['trial_days']??0,'is_active'=>isset($_POST['is_active']),'is_public'=>isset($_POST['is_public']),'is_featured'=>isset($_POST['is_featured']),'sort_order'=>$_POST['sort_order']??0]);
    $keys=$_POST['feature_key']??[]; $names=$_POST['feature_name']??[]; $enabled=$_POST['feature_enabled']??[]; $limits=$_POST['feature_limit']??[]; $orders=$_POST['feature_sort']??[];
    foreach($keys as $i=>$key){$key=trim((string)$key);$fname=trim((string)($names[$i]??''));if($key===''||$fname==='')continue;$raw=trim((string)($limits[$i]??''));$limit=$raw===''?null:(int)$raw;$repo->saveFeature($id,$key,$fname,in_array((string)$i,$enabled,true),$limit,(int)($orders[$i]??$i*10));}
    Session::flash('success','Plan updated. Changes apply immediately to new entitlement checks.'); header('Location: ' . PlatformAuth::basePath() . '/plans?edit=' . $id); exit;
   }
  }catch(Throwable $e){Session::flash('error','Could not save plan: '.$e->getMessage());}
 }
}
$plans=$repo->all(); $editId=(int)($_GET['edit']??0); $edit=$editId>0?$repo->find($editId):null;
ob_start(); ?>
