s_active']?'checked':'' ?>> Active</label><label class="form-check"><input class="form-check-input" type="checkbox" name="is_public" <?= $edit['is_public']?'checked':'' ?>> Public</label><label class="form-check"><input class="form-check-input" type="checkbox" name="is_featured" <?= $edit['is_featured']?'checked':'' ?>> Featured</label></div><h3 class="h6 fw-bold">Features and limits</h3><div class="table-responsive"><table class="table align-middle"><thead><tr><th>Key</th><th>Name</th><th>Enabled</th><th>Limit</th><th>Order</th></tr></thead><tbody><?php foreach($edit['features'] as $i=>$feature): ?><tr><td><input class="form-control form-control-sm" name="feature_key[]" value="<?= e($feature['feature_key']) ?>"></td><td><input class="form-control form-control-sm" name="feature_name[]" value="<?= e($feature['feature_name']) ?>"></td><td><input type="checkbox" class="form-check-input" name="feature_enabled[]" value="<?= $i ?>" <?= $feature['enabled']?'checked':'' ?>></td><td><input class="form-control form-control-sm" type="number" name="feature_limit[]" value="<?= $feature['limit_value']===null?'':e($feature['limit_value']) ?>" placeholder="Unlimited"></td><td><input class="form-control form-control-sm" type="number" name="feature_sort[]" value="<?= e($feature['sort_order']) ?>"></td></tr><?php endforeach; ?><tr><td><input class="form-control form-control-sm" name="feature_key[]" placeholder="products.max"></td><td><input class="form-control form-control-sm" name="feature_name[]" placeholder="Products"></td><td><input type="checkbox" class="form-check-input" name="feature_enabled[]" value="<?= count($edit['features']) ?>" checked></td><td><input class="form-control form-control-sm" type="number" name="feature_limit[]" placeholder="Unlimited"></td><td><input class="form-control form-control-sm" type="number" name="feature_sort[]" value="99"></td></tr></tbody></table></div><button class="btn btn-primary mt-3">Save plan</button></form></section><?php else: ?><div class="empty-state panel"><h2 class="h5 fw-bold">Select a plan</h2><p class="text-secondary mb-0">Choose a plan on the left to configure its prices, visibility, trial and entitlements.</p></div><?php endif; ?></div></div></div>
